// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, uint256 extraDeposits) public {
        vm.assume(target != address(0));
        // Ensure value is non-zero so that we actually send ether
        value = bound(value, 1, address(this).balance);
        // Make extraDeposits small enough to avoid overflow
        extraDeposits = bound(extraDeposits, 0, 10);
        // First, cause some deposits (or not) to set depositsCount to a non-zero value
        for (uint256 i = 0; i < extraDeposits; i++) {
            payable(address(c)).transfer(1 wei);
        }
        uint256 depositsBefore = c.depositsCount();
        // Fund this contract enough to send value
        vm.deal(address(this), value);
        // Call sendMoney — this sends ether to target which may trigger fallback if target == address(c)
        bool reverted = false;
        try c.sendMoney(target, value) {
            // success
        } catch {
            reverted = true;
        }
        uint256 depositsAfter = c.depositsCount();
        // General rule: when sendMoney is called with target == address(c), depositsCount must increase by 1
        // because the fallback will run. The mutant breaks this when depositsCount > 0 before the call.
        if (target == address(c)) {
            assertTrue(depositsAfter == depositsBefore + 1, "depositsCount should increase by 1 when ether is sent to the contract itself");
        } else {
            // For other targets, depositsCount must not change (assuming no other interactions)
            assertTrue(depositsAfter == depositsBefore, "depositsCount should not change when ether is sent elsewhere");
        }
    }
}

