pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(this).balance);
        vm.deal(address(this), value);
        vm.deal(address(c), 0);

        // Record initial balances
        uint256 initialOwnerBalance = address(c.owner()).balance;

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // Record final balances
        uint256 finalOwnerBalance = address(c.owner()).balance;

        // The rule: after sendMoney, the owner's balance equals the initial owner balance plus the value sent,
        // minus the amount that would have been withdrawn if withdraw were called with the value.
        // In the reference, funds go to msg.sender (this), not owner, so owner balance is unchanged.
        // In the buggy version, funds go to owner, so owner balance increases by value (and depositsCount is irrelevant for the balance difference).
        assertTrue(finalOwnerBalance == initialOwnerBalance + value - (success ? value : 0));
    }
}

